<template>
  <main class="monitoring-page">
    <header class="page-header"><div><p class="eyebrow">WAREHOUSE MONITORING</p><h1>仓储监控</h1><p>查看仓库区域与摄像头的实时视频状态。</p></div><div class="header-status"><span class="status-dot online"></span>{{ onlineCamerasCount }} / {{ totalCamerasCount }} 路在线</div></header>
    <section class="monitoring-workspace">
      <aside class="area-panel"><div class="panel-title"><el-icon><Location /></el-icon><span>监控区域</span></div><div class="area-list"><button v-for="area in areas" :key="area.id" class="area-item" :class="{ active: activeArea === area.id }" @click="selectArea(area)"><el-icon><component :is="area.icon" /></el-icon><span class="area-copy"><strong>{{ area.name }}</strong><small>{{ area.location }}</small></span><span class="status-dot" :class="area.status"></span></button></div></aside>
      <section class="video-panel"><div class="video-toolbar"><div><h2>{{ currentAreaName }}</h2><span><span class="status-dot" :class="currentArea?.status"></span>{{ currentStatus }}</span></div><div class="tool-actions"><el-button circle title="刷新视频流" :icon="Refresh" @click="refreshStream" /><el-button circle title="全屏" :icon="FullScreen" @click="toggleFullscreen" /><el-button circle title="截图" :icon="Camera" @click="captureScreenshot" /></div></div><div ref="videoContainer" class="video-wrapper"><VideoPlayer :key="currentStream" ref="videoPlayerRef" :stream-path="currentStream" /></div><div class="stream-metrics"><div><span>视频流</span><strong>{{ currentStream }}</strong></div><div><span>延迟</span><strong :class="latencyClass">{{ latency }} ms</strong></div><div><span>帧率</span><strong>{{ fps }} FPS</strong></div><div><span>更新时间</span><strong>{{ currentTime }}</strong></div></div></section>
      <aside class="camera-panel"><div class="panel-title"><el-icon><VideoCamera /></el-icon><span>摄像头</span><em>{{ currentCameras.length }}</em></div><div class="camera-list"><button v-for="camera in currentCameras" :key="camera.id" class="camera-item" :class="{ active: currentStream === camera.stream, offline: camera.status === 'offline' }" @click="switchCamera(camera)"><el-icon><VideoCamera /></el-icon><span class="camera-copy"><strong>{{ camera.name }}</strong><small>{{ camera.stream }}</small></span><span class="status-dot" :class="camera.status"></span></button></div></aside>
    </section>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Camera, FullScreen, Location, Refresh, VideoCamera } from '@element-plus/icons-vue'
import VideoPlayer from '@/components/VideoPlayer/VideoPlayer.vue'
type Status = 'online' | 'offline'
interface CameraInfo { id: string; name: string; stream: string; status: Status }
interface Area { id: string; name: string; location: string; icon: typeof Location; status: Status; stream: string; cameras: CameraInfo[] }
const activeArea = ref('entrance'); const currentStream = ref('/stream1'); const videoPlayerRef = ref<{ refresh?: () => void; captureScreenshot?: () => void } | null>(null); const videoContainer = ref<HTMLElement | null>(null); const latency = ref(45); const fps = ref(25); const currentTime = ref('')
const areas = ref<Area[]>([{ id: 'entrance', name: '仓库入口', location: 'A区大门', icon: Location, status: 'online', stream: '/stream1', cameras: [{ id: 'entrance-1', name: '入口主摄像头', stream: '/stream1', status: 'online' }, { id: 'entrance-2', name: '车牌识别摄像头', stream: '/stream1b', status: 'online' }] }, { id: 'storage', name: '货架区域', location: 'B区仓库', icon: VideoCamera, status: 'online', stream: '/stream2', cameras: [{ id: 'storage-1', name: '存储区全景', stream: '/stream2', status: 'online' }, { id: 'storage-2', name: 'A排货架监控', stream: '/stream2a', status: 'online' }] }, { id: 'sorting', name: '分拣区域', location: 'C区分拣台', icon: Camera, status: 'online', stream: '/stream3', cameras: [{ id: 'sorting-1', name: '分拣线全景', stream: '/stream3', status: 'online' }, { id: 'sorting-2', name: '机器人作业区', stream: '/stream3a', status: 'online' }] }, { id: 'loading', name: '装卸区域', location: 'D区装卸台', icon: Location, status: 'online', stream: '/stream4', cameras: [{ id: 'loading-1', name: '装卸台一号', stream: '/stream4', status: 'online' }, { id: 'loading-2', name: '装卸台二号', stream: '/stream4a', status: 'online' }] }, { id: 'security', name: '安防区域', location: 'E区通道', icon: VideoCamera, status: 'offline', stream: '/stream5', cameras: [{ id: 'security-1', name: '消防通道监控', stream: '/stream5', status: 'offline' }] }])
const currentArea = computed(() => areas.value.find((area) => area.id === activeArea.value)); const currentAreaName = computed(() => currentArea.value?.name ?? ''); const currentCameras = computed(() => currentArea.value?.cameras ?? []); const currentStatus = computed(() => currentArea.value?.status === 'online' ? '在线' : '离线'); const onlineCamerasCount = computed(() => areas.value.flatMap((area) => area.cameras).filter((camera) => camera.status === 'online').length); const totalCamerasCount = computed(() => areas.value.flatMap((area) => area.cameras).length); const latencyClass = computed(() => latency.value < 50 ? 'good' : latency.value < 100 ? 'warning' : 'bad')
const updateMetrics = () => { latency.value = Math.floor(Math.random() * 80) + 20; fps.value = Math.floor(Math.random() * 10) + 20; currentTime.value = new Date().toLocaleTimeString('zh-CN', { hour12: false }) }
const selectArea = (area: Area) => { activeArea.value = area.id; currentStream.value = area.stream; updateMetrics() }
const switchCamera = (camera: CameraInfo) => { if (camera.status === 'offline') { ElMessage.warning(`${camera.name} 当前离线`); return }; currentStream.value = camera.stream; updateMetrics() }
const refreshStream = () => { videoPlayerRef.value?.refresh?.(); updateMetrics(); ElMessage.success('视频流已刷新') }
const toggleFullscreen = () => { if (!document.fullscreenElement) void videoContainer.value?.requestFullscreen?.(); else void document.exitFullscreen?.() }
const captureScreenshot = () => { if (videoPlayerRef.value?.captureScreenshot) videoPlayerRef.value.captureScreenshot(); else ElMessage.info('截图功能暂不可用') }
let metricTimer: ReturnType<typeof setInterval>
onMounted(() => { updateMetrics(); metricTimer = setInterval(updateMetrics, 3000) }); onUnmounted(() => clearInterval(metricTimer))
</script>

<style scoped>
