area-item.active, .camera-item.active { border-color: #2e658a; background: #1f4058; color: #edf3f8; }.area-item > .el-icon, .camera-item > .el-icon { color: #9aabb9; font-size: 19px; }.area-copy, .camera-copy { display: flex; flex: 1; flex-direction: column; min-width: 0; gap: 4px; }.area-copy strong, .camera-copy strong { overflow: hidden; font-size: 13px; font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }.area-copy small, .camera-copy small { overflow: hidden; color: #8e9ca8; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }.status-dot { display: inline-block; flex: 0 0 auto; width: 7px; height: 7px; border-radius: 50%; }.status-dot.online { background: #72c781; box-shadow: 0 0 0 3px rgba(114, 199, 129, .13); }.status-dot.offline { background: #8e9ca8; }.video-panel { display: flex; flex-direction: column; padding: 14px; }.video-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; }.video-toolbar h2 { margin: 0 0 4px; font-size: 16px; font-weight: 600; }.video-toolbar > div:first-child > span { display: inline-flex; align-items: center; gap: 6px; color: #aebbc6; font-size: 12px; }.tool-actions { display: flex; gap: 6px; }.tool-actions :deep(.el-button) { width: 32px; height: 32px; margin: 0; border-color: #4a5661; background: #292f35; color: #aebbc6; }.tool-actions :deep(.el-button:hover) { border-color: #83c3ef; background: #3a444d; color: #83c3ef; }.video-wrapper { display: flex; flex: 1; align-items: center; justify-content: center; min-height: 260px; overflow: hidden; border: 1px solid #414b55; border-radius: 6px; background: #15191d; }.video-wrapper :deep(main), .video-wrapper :deep(video) { width: 100%; max-width: none; height: 100%; border-radius: 0; object-fit: contain; }.stream-metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin-top: 12px; }.stream-metrics > div { min-width: 0; padding: 9px 10px; border: 1px solid #414b55; border-radius: 5px; background: #292f35; }.stream-metrics span, .stream-metrics strong { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.stream-metrics span { margin-bottom: 4px; color: #8e9ca8; font-size: 11px; }.stream-metrics strong { color: #c6d0d9; font-family: Consolas, monospace; font-size: 12px; }.stream-metrics strong.good { color: #72c781; }.stream-metrics strong.warning { color: #f0c66b; }.stream-metrics strong.bad { color: #f59b9b; }@media (max-width: 1120px) { .monitoring-page { overflow: auto; }.monitoring-workspace { grid-template-columns: 210px minmax(0, 1fr); min-height: 720px; }.camera-panel { grid-column: 1 / -1; max-height: 175px; }.camera-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }.video-wrapper { min-height: 400px; } }@media (max-width: 720px) { .monitoring-page { padding: 16px 12px; }.page-header { flex-direction: column; }.monitoring-workspace { display: flex; flex-direction: column; min-height: 0; }.area-panel, .camera-panel { min-height: 170px; max-height: 200px; }.area-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }.camera-list { grid-template-columns: 1fr; }.video-panel { min-height: 470px; }.video-wrapper { min-height: 280px; }.stream-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
